window.LD=window.LD||{};window.LD["static_music"]={"music":{"songbook":[{"id":"ferrymans_daughter","title":"The Ferryman's Daughter","tone":"tender","diff":3,"craft":"fine","meter":"3/4","lines":["She rows the river when the bridge is shut","and charges nothing, which the toll-man hates","she sings the current down to the sea","and I have missed three crossings for her sake","Row me over, row me slow","the bridge can wait, the bridge can go"],"chorus":[4,5],"tags":["love","road"],"town":"carrbridge"},{"id":"lantern_window","title":"Lantern in the Window","tone":"tender","diff":2,"craft":"plain","meter":"4/4","lines":["My mother keeps a lantern lit in Thornwall","on the sill above the baker's shop","it's been burning since the spring I left","she'll know the night to let it stop","Lantern, lantern, keep the wick","I'm coming home, but not too quick"],"chorus":[4,5],"tags":["home"],"town":"thornwall"},{"id":"two_cups","title":"Two Cups of Frosthold Tea","tone":"tender","diff":1,"craft":"clumsy","meter":"3/4","lines":["I made you tea, it was too hot","I made another, it was not","the first one froze, this is Frosthold","so now we have two cups of cold","Two cups, two cups, I love you lots","and also all these frozen pots"],"chorus":[4,5],"tags":["love","home"],"town":"frosthold"},{"id":"moss_milestone","title":"Moss on the Milestone","tone":"tender","diff":4,"craft":"fine","meter":"6/8","lines":["There's moss on the milestone that says Hollowood","it grew while I was gone","the trees all know my name again","and hum it like a song","Green, green, the road runs green","back to the place I've always been"],"chorus":[4,5],"tags":["road","home"],"town":"hollowood"},{"id":"pip_never_lost","title":"Pip Has Never Lost (Except That Once)","tone":"funny","diff":2,"craft":"plain","meter":"4/4","lines":["Pip the Lutist came to town","and played the mayor's hat right off","he's never lost a single duel","except that once, he had a cough","Pip, Pip, Unstoppable Pip","mind your purse and mind your lip"],"chorus":[4,5],"tags":["work"]},{"id":"goblin_boots","title":"The Goblin Who Wanted My Boots","tone":"funny","diff":1,"craft":"clumsy","meter":"4/4","lines":["A goblin wanted my boots","I said no, he said yes","we argued till the moon came up","now he has my boots, I guess","Boots, boots, goblin boots","he wears them on his ears, the brute"],"chorus":[4,5],"tags":["monsters","road"]},{"id":"horse_opinions","title":"My Horse Has Opinions","tone":"funny","diff":2,"craft":"plain","meter":"6/8","lines":["My horse has opinions about the King's Road","and none of them are kind","she stops at every puddle, every bridge","and all the ones behind","Hup, hup, won't you go","she looks at me and she says no"],"chorus":[4,5],"tags":["road"]},{"id":"toll_carrbridge","title":"The Toll at Carrbridge","tone":"funny","diff":3,"craft":"fine","meter":"4/4","lines":["Two copper for the crossing, one for the cart","one more for the look upon your face","the toll-man keeps a ledger for your heart","and charges if you stop to ask the price","Pay the bridge, pay the bridge","pay it going over, pay it back"],"chorus":[4,5],"tags":["road","work"],"town":"carrbridge"},{"id":"undertaker_debt","title":"Debt to the Undertaker","tone":"dark","diff":4,"craft":"fine","meter":"3/4","lines":["I owe the Undertaker for a box","he measured me in Ashfen while I slept","he's patient as the fen and twice as deep","and every coin I've saved, he's kept","Not yet, not yet, says the Undertaker","but he writes my name in his book"],"chorus":[4,5],"tags":["death"],"town":"ashfen"},{"id":"seven_down","title":"Seven Down the Shaft","tone":"dark","diff":3,"craft":"plain","meter":"4/4","lines":["Seven went down the Veldrock shaft","with lamps and picks and bread","six came up at the end of shift","and one sang down below instead","Dig, dig, keep your lamp lit","sing so they know where you are"],"chorus":[4,5],"tags":["work","death"],"town":"veldrock"},{"id":"bleakmarsh_lights","title":"Bleakmarsh Lights","tone":"dark","diff":2,"craft":"plain","meter":"6/8","lines":["Don't follow the lights over Bleakmarsh","they bob like a lantern held low","they'll lead you out where the reeds are tall","and the water's a long way below","Keep to the path, keep to the path","the lights are not your friends"],"chorus":[4,5],"tags":["monsters","road"]},{"id":"round_living","title":"Another Round for the Living","tone":"rowdy","diff":2,"craft":"plain","meter":"4/4","lines":["We came back from the Goblin Camp","with mud up to the knee","so set them up and knock them down","and the first one's on me","Another round for the living","and a half for the ones who aren't"],"chorus":[4,5],"tags":["drink","monsters"]},{"id":"gruks_hat","title":"Gruk's Big Hat","tone":"rowdy","diff":1,"craft":"clumsy","meter":"4/4","lines":["Gruk the warchief has a hat","it is big and also flat","we knocked it off, imagine that","now it's a very nice doormat","Hat, hat, Gruk's big hat","hat hat hat hat hat"],"chorus":[4,5],"tags":["monsters"]},{"id":"haul_herring","title":"Haul on the Herring","tone":"rowdy","diff":3,"craft":"fine","meter":"6/8","lines":["Haul on the net when the herring run","haul when the cliffs go grey","the sea takes a tithe of every crew","but not from us today","Heave, Saltmarrow, heave and sing","the tide comes in and the tide goes out"],"chorus":[4,5],"tags":["sea","work"],"town":"saltmarrow"},{"id":"empty_bedroll","title":"The Empty Bedroll","tone":"sad","diff":4,"craft":"fine","meter":"3/4","lines":["We rolled out five at dawn today","and packed up only four","the fifth one's boots are by the fire","they won't need them anymore","Lay it down, lay it down","we'll carry what we can"],"chorus":[4,5],"tags":["death","road"]},{"id":"whitepeak_snow","title":"Whitepeak Snow","tone":"sad","diff":3,"craft":"plain","meter":"3/4","lines":["The snow came down on Whitepeak","and covered every track","I watched the pass till the light was gone","you said you'd be back","Snow on the pass, snow on the pass","I'll keep the fire till spring"],"chorus":[4,5],"tags":["road","love"],"town":"frosthold"},{"id":"old_dog","title":"My Dog Is Old Now","tone":"sad","diff":2,"craft":"plain","meter":"4/4","lines":["My dog is old, he sleeps by the fire","he chased off a wolf when he was young","now he chases rabbits in his dreams","and I let him have the last good bone","Good dog, good dog","the road was long and you walked it all"],"chorus":[4,5],"tags":["home"]},{"id":"salt_cliffs_stand","title":"The Stand at the Salt Cliffs","tone":"heroic","diff":5,"craft":"fine","meter":"4/4","lines":["The kraken rose at the Salt Cliffs","with arms like a forest of oak","six of us stood on the wet black stone","and not one ran, and not one spoke","Hold the line, hold the line","the sea can't drown us all"],"chorus":[4,5],"tags":["sea","monsters"]},{"id":"redcrag_morning","title":"Redcrag Morning","tone":"heroic","diff":3,"craft":"plain","meter":"4/4","lines":["We climbed up Redcrag in the dark","and waited for the sun","the drake was sleeping on its gold","we woke it, and we won","Red, red, the morning red","the drake is down and we're not dead"],"chorus":[4,5],"tags":["monsters","road"]},{"id":"forge_song","title":"The Ironhaven Forge Song","tone":"heroic","diff":4,"craft":"plain","meter":"4/4","lines":["Strike while the iron's yellow","fold it while it's red","a blade from the Ironhaven forge","outlives the hand, the smith said","Ring, ring, the anvil ring","a hammer and a song"],"chorus":[4,5],"tags":["work"],"town":"ironhaven"},{"id":"kobold_accountant","title":"The Kobolds' Accountant","tone":"odd","diff":2,"craft":"clumsy","meter":"4/4","lines":["The kobolds have an accountant","his name is Mister Sneeze","he counts the gold in the mine all day","and charges extra fees on cheese","Count, count, Mister Sneeze","the numbers are just numbers please"],"chorus":[4,5],"tags":["monsters","work"],"town":"veldrock"},{"id":"humming_tree","title":"The Tree That Hums","tone":"odd","diff":5,"craft":"fine","meter":"6/8","lines":["There's a tree in Hollowood that hums at night","a low note, like a cat asleep","the elders say it's dreaming of the sky","the children say it's counting sheep","Hum, hum, the old tree hums","and nobody knows what it knows"],"chorus":[4,5],"tags":["home"],"town":"hollowood"},{"id":"nibs_lament","title":"Nib's Lament","tone":"odd","diff":3,"craft":"clumsy","meter":"3/4","lines":["I am a goblin, I play checkers","I am not very good at it","I lost my board to a human","I won it back, then lost it, a bit","Jump, jump, king me please","I practise with a badger"],"chorus":[4,5],"tags":["monsters"]},{"id":"moon_owes","title":"The Moon Owes Me Money","tone":"odd","diff":3,"craft":"plain","meter":"4/4","lines":["I lent the moon a silver coin","it promised to pay it back","each month it shrinks to dodge the debt","then comes round full and bold as brass","Pay up, moon, pay up","I see you there behind the clouds"],"chorus":[4,5],"tags":["drink"]},{"id":"inga_third_coat","title":"Inga's Third Coat","tone":"tender","diff":2,"craft":"plain","meter":"3/4","lines":["Big Inga keeps a coat behind the bar","for anyone who stumbles in from snow","it smells of pipe smoke and a stranger's dog","and it's the warmest thing I know","Third coat, third coat, by the Frosthold door","there's always room for one cold traveller more"],"chorus":[4,5],"tags":["home"],"town":"frosthold"},{"id":"mended_cloak","title":"The Mended Cloak","tone":"tender","diff":3,"craft":"fine","meter":"6/8","lines":["You mended my cloak by the Thornwall gate","with thread the colour of your hair","and every rip the road has made since","has a little bit of you in there","Stitch by stitch and mile by mile","I wear you on my back a while"],"chorus":[4,5],"tags":["love","road"],"town":"thornwall"},{"id":"watching_oak","title":"Sleeping Under the Watching Oak","tone":"tender","diff":4,"craft":"fine","meter":"3/4","lines":["Fern says the old oak watches us all night","she says it like a promise, not a threat","I slept beneath it once when I was small","and it hasn't stopped watching yet","Sleep now, sleep now, the oak's awake","it keeps the dark for the dreamer's sake"],"chorus":[4,5],"tags":["home"],"town":"hollowood"},{"id":"two_loaves","title":"Two Loaves in the Lamp-Room","tone":"tender","diff":1,"craft":"plain","meter":"4/4","lines":["My father packed two loaves before each shift","one for the dark and one for the climb","he said a miner's never truly lost","while there's bread left, and there's time","Two loaves, two loaves, down the Veldrock stair","eat one going down, save one for there"],"chorus":[4,5],"tags":["home","work"],"town":"veldrock"},{"id":"letters_in_salt","title":"Letters in Salt","tone":"tender","diff":4,"craft":"fine","meter":"6/8","lines":["I write your name in salt along the rail","the spray comes up and takes it every time","I've written it from Saltmarrow to the cliffs","the sea must know it off by heart","Wash it away and I'll write it again","the tide has time, but so have I"],"chorus":[4,5],"tags":["sea","love"],"town":"saltmarrow"},{"id":"dagnys_forge","title":"Dagny at the Forge","tone":"tender","diff":2,"craft":"plain","meter":"4/4","lines":["Dagny at the forge has burns on every knuckle","and a laugh you hear three streets away","she fixed my sword and wouldn't take my coin","I've broken it four times since, to stay","Ring the anvil, Dagny, ring it slow","there's nowhere else I'd rather go"],"chorus":[4,5],"tags":["love","work"],"town":"thornwall"},{"id":"one_blanket","title":"One Blanket","tone":"tender","diff":1,"craft":"clumsy","meter":"3/4","lines":["We only had one blanket on the road","you took the blanket and I took the cold","next night it's mine and you get the cold","this is a love song, or so I'm told","One blanket, two of us, freezing in turns","that's how you know, that's how love learns"],"chorus":[4,5],"tags":["road","love"]},{"id":"last_light_road","title":"Last Light on the King's Road","tone":"tender","diff":3,"craft":"fine","meter":"4/4","lines":["The last light on the King's Road turns gold","and every cart and pilgrim slows to see","the milestones throw their shadows out like arms","and one of them is pointing home for me","Gold on the road and gold on the stone","every road's the road back home"],"chorus":[4,5],"tags":["road","home"]},{"id":"venns_candle","title":"Venn's Candle","tone":"tender","diff":2,"craft":"plain","meter":"3/4","lines":["Toll-Captain Venn keeps a candle in the window","for the carts that cross after dark","he'll still charge you two copper at the gate","but he'll walk you over with the lamp","Over the bridge, over the bridge","there's a light on the other side"],"chorus":[4,5],"tags":["road","home"],"town":"carrbridge"},{"id":"one_note_whistle","title":"The One-Note Whistle","tone":"tender","diff":1,"craft":"clumsy","meter":"6/8","lines":["My brother cut a whistle from a stick","it played one note, and the note was sick","he played it every morning anyway","I'd give my boots to hear it today","Toot, toot, a one-note tune","come home, brother, come home soon"],"chorus":[4,5],"tags":["home"],"town":"hollowood"},{"id":"ashfen_fog","title":"Ashfen Fog","tone":"tender","diff":4,"craft":"fine","meter":"3/4","lines":["The fog comes up in Ashfen thick as wool","you cannot see the lantern in your hand","but I could find your door with eyes shut","eleven planks, then the step where herons stand","Hold the lantern low, love, hold it low","the fog won't keep me, and the fog knows"],"chorus":[4,5],"tags":["love","home"],"town":"ashfen"},{"id":"kettle_on","title":"Put the Kettle On","tone":"tender","diff":1,"craft":"plain","meter":"4/4","lines":["Put the kettle on, I'm coming back","with a goblin's ear and half a map","and a story that you won't believe","and a hole in my second-best sleeve","Kettle on, kettle on","I'll be home before the water's gone"],"chorus":[4,5],"tags":["home","road"]},{"id":"stars_frostspire","title":"Stars Over Frostspire","tone":"tender","diff":5,"craft":"fine","meter":"6/8","lines":["From the top of Frostspire you can see","every lamp in every town below","I counted eight and couldn't find yours","so I counted all the stars instead, slow","One for the road and one for the cold","and one for you to have and hold"],"chorus":[4,5],"tags":["love","road"],"town":"frosthold"},{"id":"carry_you_home","title":"I'll Carry You Home","tone":"tender","diff":3,"craft":"plain","meter":"4/4","lines":["You took the arrow that was meant for me","so now it's my turn to take the weight","you're heavier than you look, my friend","and you could stop talking, it's getting late","I'll carry you home on my back","and you can tell me how to walk"],"chorus":[4,5],"tags":["road","monsters"]},{"id":"ironhaven_lullaby","title":"Ironhaven Lullaby","tone":"tender","diff":2,"craft":"plain","meter":"3/4","lines":["Hush now, the hammers are going to sleep","the bellows are breathing slow and deep","the last red spark has climbed up the flue","and Ironhaven's dreaming of you","Hush, hush, the forges are cold","sleep till the morning bell has tolled"],"chorus":[4,5],"tags":["home","work"],"town":"ironhaven"},{"id":"little_grey_shadow","title":"Little Grey Shadow","tone":"tender","diff":3,"craft":"plain","meter":"6/8","lines":["After the Wolf Den a cub trailed behind","no bigger than my boot and not afraid","we threw it bread to send it home","it ate the bread, and then it stayed","Little grey shadow, little grey shade","follow us home, you've got it made"],"chorus":[4,5],"tags":["monsters","road"]},{"id":"mug_says_grim","title":"My Mug at the Sagging Beam","tone":"tender","diff":1,"craft":"clumsy","meter":"4/4","lines":["Old Hesk has a mug with my name on","he spelt it wrong, but it's still mine","it hangs above the bar with all the others","it's been there since I was twenty-nine","Pour it full, Hesk, pour it to the brim","it's my mug, even if it says Grim"],"chorus":[4,5],"tags":["drink","home"],"town":"thornwall"},{"id":"snowshoe_waltz","title":"The Snowshoe Waltz","tone":"tender","diff":4,"craft":"fine","meter":"3/4","lines":["You can't waltz in snowshoes, Ragna said","so we waltzed in snowshoes on the frozen lake","three steps and a stumble and a laugh","and the ice held, for both our sakes","One, two, three, and a stumble, and turn","the cold is how the warm things learn"],"chorus":[4,5],"tags":["love"],"town":"frosthold"},{"id":"when_this_is_over","title":"When This Is Over","tone":"tender","diff":2,"craft":"plain","meter":"4/4","lines":["When this is over I'll keep bees","and grow fat beans along a wall","I'll let the sword rust in the shed","and never think of it at all","When this is over, when this is done","I'll fall asleep out in the sun"],"chorus":[4,5],"tags":["home"]},{"id":"mossbacks_hum","title":"Mossback's Hum","tone":"tender","diff":3,"craft":"plain","meter":"6/8","lines":["Elder Mossback blesses every road we take","with a handful of leaves and a hum","the leaves blow off by the first bend","but somehow the hum hangs on","Mm, mm, the elder's song","it walks beside you all day long"],"chorus":[4,5],"tags":["road","home"],"town":"hollowood"},{"id":"drowned_gull_bell","title":"The Bell at the Drowned Gull","tone":"sad","diff":4,"craft":"fine","meter":"3/4","lines":["A bell hangs over the Drowned Gull's bar","rung once for every boat that won't come in","Captain Brine has rung it nineteen times","and wiped the brass, and poured the gin","Don't ring the bell tonight, Captain","they might be only late"],"chorus":[4,5],"tags":["sea","death"],"town":"saltmarrow"},{"id":"one_boot","title":"We Found One Boot","tone":"sad","diff":1,"craft":"clumsy","meter":"4/4","lines":["We found one boot on the Bleakmarsh path","it was a good boot, it was brown","we looked around for the other one","we never found the rest. We sat down","One boot, one boot, still laced up tight","we'll leave a lamp out for him tonight"],"chorus":[4,5],"tags":["death","road"]},{"id":"peg_by_the_door","title":"The Peg by the Door","tone":"sad","diff":2,"craft":"plain","meter":"3/4","lines":["Your peg's still by the door, and still bare","I hang my own coat one along","the dog still lies beneath it every night","and I won't tell him that you're gone","Leave the peg, leave the peg","somebody might need it yet"],"chorus":[4,5],"tags":["home","death"]},{"id":"whitepeak_cairn","title":"Cairn on Whitepeak","tone":"sad","diff":5,"craft":"fine","meter":"6/8","lines":["We built a cairn up on Whitepeak","a stone from each of us, one from you","the wind up there takes everything","but stones are slow, and so are we","Stone on stone on the mountain's knee","the wind can wait, and so can we"],"chorus":[4,5],"tags":["death","road"],"town":"frosthold"},{"id":"letters_in_the_fire","title":"Letters in the Fire","tone":"sad","diff":3,"craft":"plain","meter":"4/4","lines":["I wrote you letters every night at camp","and burned them in the fire before the dawn","the crew all think I'm bad at spelling","they don't know who the smoke is for","Up with the smoke and up with the sparks","all the words I said in the dark"],"chorus":[4,5],"tags":["love","road"]},{"id":"knock_three","title":"Knock Three Times","tone":"sad","diff":4,"craft":"fine","meter":"3/4","lines":["They still knock on the Collapsed Mine walls","three knocks, and then they listen for reply","Brother Coal says it's been forty years","Mother Grall says knock, so knock do I","Knock, knock, knock on the stone","nobody down there should be alone"],"chorus":[4,5],"tags":["work","death"],"town":"veldrock"},{"id":"last_copper","title":"My Last Copper","tone":"sad","diff":2,"craft":"clumsy","meter":"4/4","lines":["My last copper, and I'll spend it well","on a mug of something brown I cannot smell","tomorrow I'll be poor, tonight I'm poor as well","but tonight I've got the mug as well","Last copper, last copper, rolling on the bar","that's as far as copper goes, that's far"],"chorus":[4,5],"tags":["drink"]},{"id":"mother_tides_lanterns","title":"Mother Tide's Lanterns","tone":"sad","diff":3,"craft":"plain","meter":"6/8","lines":["Mother Tide puts lanterns on the water","one for every name the sea has kept","they float out past the harbour wall","and the gulls go quiet where they've slept","Float them out on the evening tide","a light for everyone who died"],"chorus":[4,5],"tags":["sea","death"],"town":"saltmarrow"},{"id":"old_barley","title":"Old Barley","tone":"sad","diff":2,"craft":"plain","meter":"4/4","lines":["Old Barley carried us from Carrbridge to the coast","and never once complained about the load","we left him in a field of clover, lame","he watched us all the way along the road","Good horse, good horse, eat your fill","we'll come back for you over the hill"],"chorus":[4,5],"tags":["road"],"town":"carrbridge"},{"id":"rain_on_the_tent","title":"Rain on the Tent","tone":"sad","diff":3,"craft":"fine","meter":"3/4","lines":["Rain on the tent and nobody talking","we lost the fight, and the sky fell too","somebody's humming a song from home","and nobody tells them it's out of tune","Rain, rain, keep the fire low","tomorrow's dry, or so they say"],"chorus":[4,5],"tags":["road"]},{"id":"damp_lantern","title":"Light It Again, Gilda","tone":"sad","diff":2,"craft":"plain","meter":"3/4","lines":["Gilda Wetfoot lights the lantern at the door","it never catches, it's too damp","she lights it every evening all the same","for the ones still out there in the swamp","Light it, Gilda, light it again","somebody's walking home through the fen"],"chorus":[4,5],"tags":["home","death"],"town":"ashfen"},{"id":"shield_on_the_wall","title":"Her Shield on the Wall","tone":"sad","diff":4,"craft":"fine","meter":"4/4","lines":["Her shield hangs in the Gilded Flagon now","with every dent still in it, every one","Madame Ostrava dusts it on rest-days","and counts the dents, and stops at one","Hang it high and hang it straight","she held the line, she held the gate"],"chorus":[4,5],"tags":["death","monsters"],"town":"ironhaven"},{"id":"forgot_the_words","title":"I Forgot the Words","tone":"sad","diff":1,"craft":"clumsy","meter":"3/4","lines":["My mother sang a song when I was small","I've forgotten all the words but one","the word was little, I think, or bell","I sing it anyway, the bit that's left","La la little, la la bell","I don't remember, but I remember well"],"chorus":[4,5],"tags":["home"]},{"id":"the_last_watch","title":"The Last Watch","tone":"sad","diff":4,"craft":"fine","meter":"6/8","lines":["I'll take the last watch, you go and sleep","the fire's low and all the stars are out","and if something comes out of the dark","you won't ever hear me shout","Sleep now, I've got the watch tonight","sleep now, I'll hold the light"],"chorus":[4,5],"tags":["road","death"]},{"id":"ash_over_redcrag","title":"Ash Over Redcrag","tone":"sad","diff":3,"craft":"plain","meter":"4/4","lines":["The drake came down on the farms below Redcrag","and the barley's ash, the barns are bone","the family's living in the ditch now","but they kept the gate, the gate is stone","Plant it again, plant it again","barley comes back after the rain"],"chorus":[4,5],"tags":["monsters","home"]},{"id":"jolly_mott","title":"Not So Jolly Mott","tone":"sad","diff":2,"craft":"plain","meter":"3/4","lines":["After closing at the Honest Toll","Jolly Mott is not so jolly","he wipes the same clean cup for an hour","and talks to the empty chair, softly","Jolly Mott, jolly Mott, pour one more","for the chair beside the door"],"chorus":[4,5],"tags":["drink","death"],"town":"carrbridge"},{"id":"long_winter","title":"The Long Winter","tone":"sad","diff":3,"craft":"plain","meter":"3/4","lines":["The winter came in early to Frosthold","and stayed till the kettles froze on the stove","Big Inga gave away the last of the bread","and Father Hoarfrost gave away his coat","Long, long, the winter's long","we'll get through it with a song"],"chorus":[4,5],"tags":["home"],"town":"frosthold"},{"id":"the_other_road","title":"The One Who Took the Other Road","tone":"sad","diff":3,"craft":"fine","meter":"4/4","lines":["You took the left fork at the milestone","we took the right, the way we'd planned","it's been a week and I still look back","at every bend, in case you changed your mind","Left road, right road, all roads bend","maybe they meet again at the end"],"chorus":[4,5],"tags":["road","love"]},{"id":"old_sword","title":"My Old Sword","tone":"sad","diff":2,"craft":"plain","meter":"4/4","lines":["I sold my old sword in Ironhaven","for a better one with a jewel","it was nicked and bent and ugly","and it saved my life, the fool, the fool","Old sword, old sword, on the dealer's rack","I hope whoever buys you brings you back"],"chorus":[4,5],"tags":["work"],"town":"ironhaven"},{"id":"season_ending","title":"The Season's Ending","tone":"sad","diff":3,"craft":"fine","meter":"3/4","lines":["The season's ending and the roads are thinning","the crews are packing, saying next year","nobody says the other thing about next year","how some of us will not be here","Raise a cup to next year","raise it high and keep it near"],"chorus":[4,5],"tags":["road","drink"]},{"id":"lizard_not_dead","title":"The Lizard Who Didn't Move","tone":"funny","diff":1,"craft":"clumsy","meter":"4/4","lines":["My lizard didn't move for seven days","I thought for sure that he was dead","I dug a hole and sang a little song","he climbed out and bit me on the head","Lizard, lizard, are you there","he blinks, which means he doesn't care"],"chorus":[4,5],"tags":["home"]},{"id":"rennets_cheese","title":"Rennet's Cheese","tone":"funny","diff":2,"craft":"plain","meter":"4/4","lines":["Rennet sells a cheese in Ashfen market","it's green, and that's the outside of it","he says it's aged inside a hollow log","the log moved out, it couldn't stand it","Rennet's cheese, Rennet's cheese","it walks to the table, if you please"],"chorus":[4,5],"tags":["work","drink"],"town":"ashfen"},{"id":"corwens_ring","title":"Fat Corwen's Ring","tone":"funny","diff":3,"craft":"plain","meter":"6/8","lines":["Fat Corwen sold me a magic ring","he said it made you hard to see","I wore it into the Goblin Camp","and every goblin could see me","Corwen, Corwen, I want my coin","he says the ring is being coy"],"chorus":[4,5],"tags":["monsters","work"],"town":"thornwall"},{"id":"third_chest","title":"Never Open the Third Chest","tone":"funny","diff":4,"craft":"fine","meter":"4/4","lines":["The first chest held a silver cup","the second held a crown","the third one had a tongue and teeth","and wouldn't put me down","Leave the third chest well alone","it's had a taste, and it wants a bone"],"chorus":[4,5],"tags":["monsters"]},{"id":"wizard_cooks","title":"Who Let the Wizard Cook","tone":"funny","diff":1,"craft":"clumsy","meter":"4/4","lines":["Who let the wizard make the stew","it's purple and it hums","it ate the spoon, it ate the pot","it's watching us, and it has thumbs","Who let the wizard cook","nobody look, nobody look"],"chorus":[0,4,5],"tags":["road"]},{"id":"mule_tax","title":"The Mule Tax","tone":"funny","diff":3,"craft":"fine","meter":"4/4","lines":["They taxed my mule at Carrbridge for its ears","a copper each, the Toll-Captain said","I said the ears are part of the mule","he said then pay me for the head","Pay for the ears and pay for the tail","Carrbridge never had a toll that failed"],"chorus":[4,5],"tags":["road","work"],"town":"carrbridge"},{"id":"snoring_guard","title":"The Snoring Guard","tone":"funny","diff":2,"craft":"plain","meter":"4/4","lines":["Somebody's snoring in the tent tonight","it shakes the poles and frightens off the wolves","we held a vote, and we're keeping them","as long as wolves are what it solves","Snore, snore, our secret ward","nothing gets past the snoring guard"],"chorus":[4,5],"tags":["road","monsters"]},{"id":"paid_in_soup","title":"Paid in Soup","tone":"funny","diff":2,"craft":"clumsy","meter":"6/8","lines":["I sang all night at the Pickaxe and Pint","Mother Grall paid me in soup","the soup had a whole pickaxe in it","I'm not complaining, it was good soup","Pay the bard, pay the bard","anything but soup, it's getting hard"],"chorus":[4,5],"tags":["drink","work"],"town":"veldrock"},{"id":"dear_yeti_society","title":"Dear Yeti Society","tone":"funny","diff":4,"craft":"fine","meter":"4/4","lines":["Dear Yeti Society, I've seen one","tall and white, it walked on two feet","it was Big Inga in her winter coat","please send the reward to the usual street","Dear sirs, dear sirs, I have proof","a footprint, a hair, and half a roof"],"chorus":[4,5],"tags":["monsters","home"],"town":"frosthold"},{"id":"kissed_a_frog","title":"I Kissed a Frog in Ashfen","tone":"funny","diff":2,"craft":"clumsy","meter":"3/4","lines":["I kissed a frog in Ashfen for a dare","it didn't turn into a prince","it turned into a bigger frog","and it's followed me around ever since","Ribbit, ribbit, my true love","it sits on my head like a damp glove"],"chorus":[4,5],"tags":["love","monsters"],"town":"ashfen"},{"id":"the_shortcut","title":"The Shortcut","tone":"funny","diff":2,"craft":"plain","meter":"4/4","lines":["Take the shortcut, said the map, through Bleakmarsh","so we took it in the spring","it's autumn now, the map's a hat","and I have learned a thing","Never take the shortcut","the shortcut takes you"],"chorus":[4,5],"tags":["road"]},{"id":"helmet_stuck","title":"My Helmet's Stuck","tone":"funny","diff":1,"craft":"clumsy","meter":"4/4","lines":["My helmet's stuck, I cannot see","a goblin's laughing, probably at me","I swing my sword where he was standing","I hit a tree, it was a hard landing","Helmet, helmet, come off my head","I'll polish you nice when the goblin's dead"],"chorus":[4,5],"tags":["monsters"]},{"id":"guild_has_rules","title":"The Guild Has Rules","tone":"funny","diff":4,"craft":"fine","meter":"4/4","lines":["The guild has rules on holding a hammer","and rules for how you hold the rules","Bertil Hammerhand has written every one","and throws the book at apprentice fools","Rule one, rule two, rule three hundred and four","rule three hundred and five: don't ask for more"],"chorus":[4,5],"tags":["work"],"town":"ironhaven"},{"id":"gulls_took_lunch","title":"The Gulls Took My Lunch","tone":"funny","diff":2,"craft":"plain","meter":"6/8","lines":["I sat on the harbour wall with a pie","a gull came down and took the crust","a second gull came and took the rest","a third gull took my trust","Gulls, gulls, Saltmarrow gulls","they'll have your lunch, your boat and your hulls"],"chorus":[4,5],"tags":["sea"],"town":"saltmarrow"},{"id":"troll_toll","title":"The Troll Who Kept No Bridge","tone":"funny","diff":3,"craft":"fine","meter":"3/4","lines":["A swamp troll sat beneath a Bleakmarsh bridge","and asked a copper of each passer-by","nobody had the heart to tell him","the bridge fell down in his grandfather's time","Pay the troll, pay the troll","he's practising for Carrbridge, bless his soul"],"chorus":[4,5],"tags":["monsters","road"]},{"id":"healers_had_enough","title":"The Healer's Had Enough","tone":"funny","diff":3,"craft":"plain","meter":"4/4","lines":["Our healer says she's had enough of us","we keep getting stabbed in the same place","she's stitched my left leg seven times","she's started stitching on a smiling face","Stitch me up, stitch me up, sigh","one more time and then goodbye"],"chorus":[4,5],"tags":["work","road"]},{"id":"rat_in_a_hat","title":"The Rat in the Warden's Hat","tone":"funny","diff":2,"craft":"clumsy","meter":"4/4","lines":["The biggest rat in Veldrock wears a hat","he stole it off of Warden Plumb","the Warden wants it back, but the rat","is calling himself the Warden. Dumb","Rat in a hat, rat in a hat","the Warden's furious, and that is that"],"chorus":[4,5],"tags":["monsters","home"],"town":"veldrock"},{"id":"drinking_skeleton","title":"Drinking With the Skeleton","tone":"funny","diff":4,"craft":"fine","meter":"6/8","lines":["I drank with a skeleton in the Ashveil Crypts","he poured, I drank, his went straight through","it puddled round his knucklebones","he said it always does, it's true","Cheers to the dead, they pour it right","it just won't stay down for the night"],"chorus":[4,5],"tags":["drink","death"]},{"id":"brave_and_fast","title":"Brave and Fast","tone":"funny","diff":2,"craft":"plain","meter":"4/4","lines":["Some heroes stand and some heroes fight","and some are very quick at night","I've never lost a single race","against a monster's angry face","Run, run, the bravest kind","I left my fear and my boots behind"],"chorus":[4,5],"tags":["monsters"]},{"id":"isa_wont_haggle","title":"Isa Tinwright Won't Haggle","tone":"funny","diff":1,"craft":"clumsy","meter":"3/4","lines":["Isa Tinwright will not haggle, no","I offered six, she said it's ten","I offered seven, she said eleven","I left, and then came back again","Twelve, said Isa, twelve it is","and that is how Isa's business is"],"chorus":[4,5],"tags":["work"],"town":"veldrock"},{"id":"nineteen_spoons","title":"Nineteen Spoons","tone":"odd","diff":1,"craft":"clumsy","meter":"4/4","lines":["My grandmother left me nineteen spoons","and a note that said don't count them","I counted them, and there were twenty","I don't know where the last one's from","Spoon, spoon, the extra spoon","it wasn't there this afternoon"],"chorus":[4,5],"tags":["home"]},{"id":"wisp_wants_a_name","title":"The Wisp Who Wanted a Name","tone":"odd","diff":4,"craft":"fine","meter":"6/8","lines":["A wisp came bobbing out of Bleakmarsh","and asked me what its name might be","I said I'd think about it overnight","it's waited by my tent for weeks, politely","Little light, little light","I'll call you Something, if that's all right"],"chorus":[4,5],"tags":["monsters","road"]},{"id":"my_friend_slime","title":"My Friend Is a Slime","tone":"odd","diff":2,"craft":"plain","meter":"4/4","lines":["My friend's a slime from the Sunken Vault","he's mostly water, partly lunch","he follows me at an inch an hour","he'll get here next spring, I've a hunch","Slime, slime, take your time","you're my friend, and you're doing fine"],"chorus":[4,5],"tags":["monsters"]},{"id":"bells_of_thornmere","title":"The Bells of Thornmere","tone":"odd","diff":5,"craft":"fine","meter":"3/4","lines":["In Thornmere Ruins there are bells with no tower","they ring alone when the moon is full","nobody hung them, nobody swings them","and they ring a tune I nearly know","Ding, dong, the bells of nowhere","ringing for a town that isn't there"],"chorus":[4,5],"tags":["home","death"],"town":"thornwall"},{"id":"lava_hug","title":"The Golem Who Wanted a Hug","tone":"odd","diff":3,"craft":"clumsy","meter":"4/4","lines":["Down in Emberdeep a golem sat alone","made of fire and made of stone","it held its arms out every time we passed","we never stayed to see how long hugs last","Warm, too warm, a lava hug","you'd come out of it a crispy bug"],"chorus":[4,5],"tags":["monsters"]},{"id":"road_walks_at_night","title":"The Road Walks at Night","tone":"odd","diff":4,"craft":"fine","meter":"6/8","lines":["They say the King's Road walks at night","it gets up, stretches, lies down again","that's why the milestones never match","and the inn is never where it's been","Walk, road, walk while we sleep","but leave us somewhere warm to keep"],"chorus":[4,5],"tags":["road"]},{"id":"crow_keeps_score","title":"The Crow Who Keeps Score","tone":"odd","diff":2,"craft":"plain","meter":"3/4","lines":["There's a crow that follows our crew","it caws once whenever we win a fight","it caws twice whenever we lose","last night it cawed all night","Caw, caw, what's the score","the crow's not saying any more"],"chorus":[4,5],"tags":["road","monsters"]},{"id":"hag_mothers_recipe","title":"The Hag Mother's Recipe","tone":"odd","diff":4,"craft":"fine","meter":"4/4","lines":["The Hag Mother gave me her recipe","for pie, she said, it's very old","it calls for one cup of thunder","and a pinch of somebody's cold","Stir it left and stir it right","and don't look in the pot at night"],"chorus":[4,5],"tags":["monsters","home"]},{"id":"kraken_writes_back","title":"The Kraken Writes Back","tone":"odd","diff":2,"craft":"clumsy","meter":"6/8","lines":["I wrote a letter to the kraken","and threw it off the Saltmarrow quay","a week later there was an answer","written in ink, all over me","Dear kraken, dear kraken, how are you","it wrote back: wet. And: hungry too"],"chorus":[4,5],"tags":["sea","monsters"],"town":"saltmarrow"},{"id":"sheep_count_back","title":"The Sheep Count Back","tone":"odd","diff":2,"craft":"plain","meter":"4/4","lines":["I counted sheep to fall asleep","at two hundred, one sheep stopped","it turned around and counted me","and somewhere there the counting dropped","One sheep, two sheep, one of me","I'm the one it can't count, apparently"],"chorus":[4,5],"tags":["home"]},{"id":"skeleton_in_ferns_garden","title":"The Skeleton in Fern's Garden","tone":"odd","diff":3,"craft":"plain","meter":"3/4","lines":["There's a skeleton in Fern's garden","nobody's sure how long it's been","moss grows on it, and a little fern","the children dress it up in green","Good morning, bones, says everyone","and the bones say nothing, in the sun"],"chorus":[4,5],"tags":["death","home"],"town":"hollowood"},{"id":"sword_that_hums","title":"The Sword That Hums","tone":"odd","diff":5,"craft":"fine","meter":"4/4","lines":["My sword hums when there's trouble near","a low note, like a nervous bee","it hummed all night outside Emberdeep","it's humming now. It's looking at me","Hum, hum, steel on the knee","what is it, sword, what do you see"],"chorus":[4,5],"tags":["monsters","work"]},{"id":"toll_for_fish","title":"The Toll for Fish","tone":"odd","diff":2,"craft":"plain","meter":"6/8","lines":["Toll-Captain Venn now charges fish","a copper each to pass the bridge","the fish won't pay, the fish swim under","so Venn has strung a net along the ridge","Fish, fish, pay your way","the river's open, but not today"],"chorus":[4,5],"tags":["road","work"],"town":"carrbridge"},{"id":"ghost_orders_wine","title":"The Ghost Who Orders Wine","tone":"odd","diff":4,"craft":"fine","meter":"3/4","lines":["Madame Ostrava keeps a table free","for the ghost who orders wine at nine","she pours it, and it goes down slowly","and leaves a coin from some old king's time","Pour for the ghost, pour for the ghost","he tips the best and talks the least"],"chorus":[4,5],"tags":["death","drink"],"town":"ironhaven"},{"id":"canary_sings_bass","title":"The Canary Who Sings Bass","tone":"odd","diff":3,"craft":"plain","meter":"4/4","lines":["In Veldrock there's a canary that sings bass","deep as a bucket going down","the miners say it is a warning","the canary says it's just its sound","Boom, boom, little bird","the strangest singing ever heard"],"chorus":[4,5],"tags":["work"],"town":"veldrock"},{"id":"heron_king","title":"The Heron King","tone":"odd","diff":4,"craft":"fine","meter":"6/8","lines":["The herons in Ashfen have a king","he stands on one leg in the reeds","Constable Damp salutes him every morning","and the king looks the other way","Long live the heron king","he doesn't do a single thing"],"chorus":[4,5],"tags":["home"],"town":"ashfen"},{"id":"haunted_dice","title":"My Dice Are Haunted","tone":"odd","diff":2,"craft":"clumsy","meter":"4/4","lines":["My dice are haunted, they only roll a three","I roll them twice, it's three and three","I bought new dice, they roll threes too","I think the ghost has followed me","Three, three, always three","a ghost who's really into three"],"chorus":[4,5],"tags":["drink","death"]},{"id":"snail_race","title":"The Hollowood Snail Race","tone":"odd","diff":1,"craft":"plain","meter":"3/4","lines":["Every spring in Hollowood they race the snails","the race takes seven days","Tobble's snail has won it twice","by going the other way","Go, snail, go, snail, slow","nobody's in a hurry, so"],"chorus":[4,5],"tags":["home"],"town":"hollowood"},{"id":"frost_giant_market","title":"The Frost Giant Comes to Market","tone":"odd","diff":3,"craft":"fine","meter":"4/4","lines":["Once a year a frost giant comes to Frosthold","to buy a single needle and some thread","Ragna sells it to him very carefully","and nobody asks what he's mending, or why","Big hands, small thread","nobody asks, and nothing's said"],"chorus":[4,5],"tags":["monsters","work"],"town":"frosthold"},{"id":"dragon_counts_sheep","title":"The Dragon Dreams of Sheep","tone":"odd","diff":5,"craft":"fine","meter":"6/8","lines":["The dragon under Redcrag dreams of sheep","it counts them as they jump the moon","and every time it gets to a hundred","some farmer's short a sheep by noon","Sleep, dragon, sleep and count","and never reach the full amount"],"chorus":[4,5],"tags":["monsters"]},{"id":"sunken_vault","title":"Down in the Sunken Vault","tone":"dark","diff":5,"craft":"fine","meter":"6/8","lines":["Down in the Sunken Vault the gold is green","and the doors swing slowly with the tide","a crown sits on a drowned king's head","and an empty seat beside","Down, down, where the lanterns drown","nobody comes back up with the crown"],"chorus":[4,5],"tags":["sea","death"],"town":"saltmarrow"},{"id":"necromancers_wedding","title":"The Necromancer's Wedding","tone":"dark","diff":3,"craft":"plain","meter":"3/4","lines":["The necromancer married in the Ashveil Crypts","the guests were very quiet, very thin","the bride wore white, and the white was bone","the vows said till death, and then again","Dance, dance, the bony dance","everybody's welcome, nobody's got a chance"],"chorus":[4,5],"tags":["death","love"]},{"id":"dont_listen","title":"Don't Listen to the Singing","tone":"dark","diff":3,"craft":"plain","meter":"6/8","lines":["If you hear a singing past the Salt Cliffs","stuff your ears with wax and bread","the voice will know your mother's name","and every word you ever said","Don't listen, don't listen","row, and don't look back"],"chorus":[4,5],"tags":["sea","monsters"]},{"id":"spider_queens_larder","title":"The Spider Queen's Larder","tone":"dark","diff":3,"craft":"plain","meter":"4/4","lines":["The Spider Queen keeps a larder","wrapped up neat and hung in rows","most of them are goblins","and one of them still wears my clothes","Silk, silk, soft and grey","she'll keep you fresh for another day"],"chorus":[4,5],"tags":["monsters"]},{"id":"bandit_laughed","title":"The Bandit Captain Laughed","tone":"dark","diff":2,"craft":"plain","meter":"4/4","lines":["The bandit captain laughed when they caught him","he laughed all the way up the hill","he laughed when they asked for his last words","they think he might be laughing still","Ha, ha, the hill is high","nobody knows what the joke was, or why"],"chorus":[4,5],"tags":["death","road"]},{"id":"rider_who_doesnt_stop","title":"The Rider Who Doesn't Stop","tone":"dark","diff":4,"craft":"fine","meter":"3/4","lines":["On the King's Road past the second milestone","a rider passes you without a sound","the horse is grey, the rider's greyer","and neither of them touches the ground","Don't wave, don't call, don't follow","the road behind him's always hollow"],"chorus":[4,5],"tags":["death","road"]},{"id":"undertakers_tape","title":"The Undertaker's Tape","tone":"dark","diff":2,"craft":"plain","meter":"4/4","lines":["The Undertaker walks through Ashfen with a tape","and measures everyone he meets","he writes it in a little book","and tips his hat, and then retreats","Mind the tape and mind the book","never let him take a second look"],"chorus":[4,5],"tags":["death"],"town":"ashfen"},{"id":"something_in_the_bog","title":"Something in the Bog","tone":"dark","diff":1,"craft":"clumsy","meter":"4/4","lines":["Something in the bog grabbed my foot","I said excuse me, it said no","I left the boot and left the sock","I left in quite a hurry, so","Squelch, squelch, mind your feet","something in the bog wants something to eat"],"chorus":[4,5],"tags":["monsters","road"]},{"id":"the_crows_know","title":"The Crows Know","tone":"dark","diff":3,"craft":"plain","meter":"6/8","lines":["The crows were on the fence before the fight","they always know, the crows","they sat and waited, patient as old priests","and counted us in rows","Caw, caw, not tonight","not tonight, we'll be all right"],"chorus":[4,5],"tags":["death","monsters"]},{"id":"bride_in_the_mere","title":"The Bride in the Mere","tone":"dark","diff":5,"craft":"fine","meter":"3/4","lines":["She walked into the mere on her wedding day","flowers in her hair, her shoes in hand","the groom is waiting at the chapel door","a hundred years, and still he stands","Ring, wedding bell, under the water","nobody's coming to give away the daughter"],"chorus":[4,5],"tags":["love","death"]},{"id":"troll_counts_supper","title":"The Troll Counts Its Supper","tone":"dark","diff":2,"craft":"clumsy","meter":"4/4","lines":["The cave troll counts on its fingers","one, two, five, a lot","it's counting us for supper","and it's very sure it's got the lot","One, two, five, a lot","run before it finds the pot"],"chorus":[4,5],"tags":["monsters"]},{"id":"ice_wraiths_breath","title":"The Ice Wraith's Breath","tone":"dark","diff":4,"craft":"plain","meter":"6/8","lines":["Don't sleep out past the Frosthold wall","the ice wraith breathes on sleeping folk","you'll wake up warm and very tired","and then you won't wake up at all","Keep the fire and keep it high","the cold is patient, and so's the sky"],"chorus":[4,5],"tags":["death","monsters"],"town":"frosthold"},{"id":"what_went_in_the_furnace","title":"What Went in the Furnace","tone":"dark","diff":3,"craft":"plain","meter":"4/4","lines":["There's a furnace under Ironhaven never out","they say a guildmaster fell in, long ago","the steel from it comes out a little red","and a little warm, and a little slow","Feed the furnace, feed it well","it keeps a secret it'll never tell"],"chorus":[4,5],"tags":["work","death"],"town":"ironhaven"},{"id":"whistle_deep_shaft","title":"The Whistle in the Deep Shaft","tone":"dark","diff":4,"craft":"fine","meter":"3/4","lines":["In the deepest shaft at Veldrock someone whistles","the same four notes they whistled long ago","Warden Plumb has sealed it twice","and twice the seal came off below","Who's whistling, who's whistling down there","don't whistle back, don't you dare"],"chorus":[4,5],"tags":["work","death"],"town":"veldrock"},{"id":"bones_wolf_den","title":"Bones at the Wolf Den","tone":"dark","diff":2,"craft":"clumsy","meter":"6/8","lines":["We found some bones in the Wolf Den","we hoped that they were deer","one of them was wearing a ring","so now we're not so sure, I fear","Bones, bones, whose are those","nobody asks, and nobody knows"],"chorus":[4,5],"tags":["monsters","death"]},{"id":"dice_with_the_dead","title":"Dice With the Dead","tone":"dark","diff":3,"craft":"plain","meter":"4/4","lines":["I played dice with a dead man in Ashfen","he never blinked and he never lost","I bet my coin and I bet my boots","he asked me what my shadow cost","Roll, roll, the bones are cold","never bet more than you can hold"],"chorus":[4,5],"tags":["drink","death"],"town":"ashfen"},{"id":"the_hollow_tree","title":"The Hollow Tree","tone":"dark","diff":3,"craft":"plain","meter":"3/4","lines":["There's a hollow tree deep in the Greenwood","where children go to hide from rain","it's big inside, much bigger than it looks","and some of them don't come out again","Count the children, count them twice","the hollow tree is not so nice"],"chorus":[4,5],"tags":["monsters","home"],"town":"hollowood"},{"id":"brasks_cell","title":"Sergeant Brask's Cell","tone":"dark","diff":2,"craft":"clumsy","meter":"4/4","lines":["Sergeant Brask has a cell with no window","and a door that only locks one way","he says a fellow went in there in spring","and he says he's in there still today","Mind your manners, mind your purse","Brask's cell could be worse, but not much worse"],"chorus":[4,5],"tags":["home"],"town":"thornwall"},{"id":"crossroads_fiddler","title":"The Fiddler at the Crossroads","tone":"dark","diff":4,"craft":"fine","meter":"6/8","lines":["At midnight where the four roads cross","a fiddler plays for anyone who'll stay","he plays so well you'll dance until you drop","and he takes your shoes and walks away","Don't dance, don't dance, keep your feet","the fiddler's always paid, and the fee's your feet"],"chorus":[4,5],"tags":["road","death"]},{"id":"slime_ate_the_cook","title":"The Slime Ate the Cook","tone":"dark","diff":1,"craft":"clumsy","meter":"4/4","lines":["The slime ate the cook on the second floor","it ate his ladle and his hat","we fought the slime and won the fight","the stew got better after that","Poor cook, poor cook, inside the goo","at least he's finally in the stew"],"chorus":[4,5],"tags":["monsters","death"]},{"id":"mirror_in_the_crypt","title":"The Mirror in the Crypt","tone":"dark","diff":3,"craft":"plain","meter":"3/4","lines":["There's a mirror in the Ashveil Crypts","that shows you as you'll be","I looked in it and saw a skull","wearing my hat, which was me","Don't look, don't look in the glass","it shows what comes, and not what was"],"chorus":[4,5],"tags":["death"]},{"id":"pick_and_pint","title":"Pick and Pint","tone":"rowdy","diff":2,"craft":"plain","meter":"4/4","lines":["Down the shaft at sunrise, up at dark","to the Pickaxe and Pint with the dust on","Mother Grall's got a barrel with our names on","we'll drink it down till the names are gone","Pick and pint, pick and pint","dig all day and sing all night"],"chorus":[4,5],"tags":["drink","work"],"town":"veldrock"},{"id":"beam_came_down","title":"The Night the Beam Came Down","tone":"rowdy","diff":1,"craft":"clumsy","meter":"4/4","lines":["The Sagging Beam was sagging when we came in","it sagged some more when we sat down","it sagged right through when the singing started","now it's the Fallen Beam all over town","Sag, sag, sag, the beam","louder, friends, it's not as bad as it seems"],"chorus":[4,5],"tags":["drink"],"town":"thornwall"},{"id":"haul_for_brine","title":"Haul Away for Captain Brine","tone":"rowdy","diff":3,"craft":"plain","meter":"6/8","lines":["Captain Brine has hung his anchor up","but he hasn't hung his voice","he sings the old songs at the Drowned Gull","and the whole bar has no choice","Haul away, haul away for Brine","the sea's still in him, and so's the wine"],"chorus":[4,5],"tags":["sea","drink"],"town":"saltmarrow"},{"id":"goblin_stomp","title":"The Goblin Stomp","tone":"rowdy","diff":2,"craft":"plain","meter":"4/4","lines":["The goblins have a dance they do","it's mostly stomping on your toes","we learned it at the Goblin Camp","and now we do it everywhere we go","Stomp, stomp, the goblin way","stomp all night and sleep all day"],"chorus":[4,5],"tags":["monsters","drink"]},{"id":"bang_on_the_table","title":"Bang on the Table","tone":"rowdy","diff":1,"craft":"clumsy","meter":"4/4","lines":["Bang on the table, bang on the table","bang on the table with your cup","bang on the table till the table breaks","then bang the floor, and pick it up","Bang, bang, bang it loud","the keeper's crying, and the keeper's proud"],"chorus":[0,4,5],"tags":["drink"]},{"id":"brass_horn_parade","title":"The Brass Horn Parade","tone":"rowdy","diff":4,"craft":"fine","meter":"4/4","lines":["Once a year the guild parades down Anvil Street","with brass horns, banners and a goat","nobody knows what the goat is for","but the goat can hold the longest note","Blow the horn and beat the drum","here the guild and the goat both come"],"chorus":[4,5],"tags":["work","home"],"town":"ironhaven"},{"id":"mead_third_coat","title":"Mead at the Third Coat","tone":"rowdy","diff":2,"craft":"plain","meter":"3/4","lines":["It's colder than a yeti's toes outside","but Big Inga's got the mead on the fire","we'll drink until we can't feel the cold","and then until we can't feel the chair","Mead, mead, warm and gold","Frosthold's only good for keeping cold"],"chorus":[4,5],"tags":["drink"],"town":"frosthold"},{"id":"someone_buy_a_round","title":"Someone Buy a Round","tone":"rowdy","diff":2,"craft":"plain","meter":"4/4","lines":["We went into the Cragtooth Warren","and came out with all our teeth","well, nearly all, and nearly us","and a kobold's helmet underneath","We won, we won, someone buy a round","the kobolds are crying underground"],"chorus":[4,5],"tags":["monsters","drink"]},{"id":"boar_chased_us","title":"The Boar Chased Us Round the Field","tone":"rowdy","diff":2,"craft":"clumsy","meter":"6/8","lines":["We went out to hunt the boar","the boar went out to hunt us","it chased us round the field three times","and won, without a fuss","Oink, oink, run for the gate","the boar is fast and we are late"],"chorus":[4,5],"tags":["monsters"]},{"id":"bridge_reel","title":"The Bridge Reel","tone":"rowdy","diff":4,"craft":"fine","meter":"6/8","lines":["Half of Carrbridge dances on the north bank","the other half dances on the south","they meet in the middle at midsummer","and somebody goes in, feet first or mouth","Over the bridge and back again","the pipes won't stop, so neither will we, then"],"chorus":[4,5],"tags":["home","drink"],"town":"carrbridge"},{"id":"kick_in_the_door","title":"Kick in the Door","tone":"rowdy","diff":3,"craft":"plain","meter":"4/4","lines":["Kick in the door and shout our names","the dungeon's going to know we came","the rats will run, the bats will flee","and the treasure's going home with me","Kick in the door, kick in the door","there's always one more floor"],"chorus":[4,5],"tags":["monsters"]},{"id":"frog_choir","title":"The Frog Choir","tone":"rowdy","diff":1,"craft":"clumsy","meter":"3/4","lines":["The frogs outside the Damp Lantern sing all night","so we sing back at them, louder still","Gilda says it's either frogs or us","and the frogs have paid their bill","Croak, croak, sing it again","nobody out-sings the frogs of the fen"],"chorus":[4,5],"tags":["drink","home"],"town":"ashfen"},{"id":"toast_to_the_bandits","title":"A Toast to the Bandits","tone":"rowdy","diff":3,"craft":"plain","meter":"4/4","lines":["Here's to the bandits on the King's Road","who took my purse and left my hat","there was nothing in the purse but a button","and they were very cross at that","Here's to the bandits, raise a cup","they robbed me blind and I cheered them up"],"chorus":[4,5],"tags":["drink","road"]},{"id":"last_one_standing","title":"Last One Standing","tone":"rowdy","diff":2,"craft":"clumsy","meter":"4/4","lines":["One mug, two mugs, three mugs, four","five mugs, then I'm on the floor","from down here the ceiling's nice","I'd like to say so, maybe twice","Last one standing wins the night","I'm not standing, but that's all right"],"chorus":[4,5],"tags":["drink"]},{"id":"acorn_ale","title":"Acorn Ale","tone":"rowdy","diff":2,"craft":"plain","meter":"6/8","lines":["In Hollowood they brew it out of acorns","it tastes like a tree that's had a week","Fern pours it in a wooden cup","and three cups in, the trees all speak","Acorn ale, acorn ale","drink it before the trees tell the tale"],"chorus":[4,5],"tags":["drink","home"],"town":"hollowood"},{"id":"here_comes_the_crew","title":"Here Comes the Crew","tone":"rowdy","diff":2,"craft":"plain","meter":"4/4","lines":["Here comes the crew, mud to the knee","loud as a wagon full of geese","the town shuts all its windows when we come","and opens the tavern, if you please","Here comes the crew, here comes the crew","lock up your pies and your chickens too"],"chorus":[4,5],"tags":["road","drink"]},{"id":"goat_on_the_roof","title":"Who Put the Goat on the Roof","tone":"rowdy","diff":1,"craft":"clumsy","meter":"3/4","lines":["I woke to find a goat on the roof","nobody's sure how it got there, me neither","the goat seems fine, the goat seems pleased","the goat's the tavern's keeper now, either","Who put the goat up on the roof","nobody did it, and we've got no proof"],"chorus":[4,5],"tags":["drink"]},{"id":"redcrag_climb","title":"Climbing Redcrag","tone":"rowdy","diff":3,"craft":"plain","meter":"4/4","lines":["Up the Redcrag, one more hold","the rock is hot and the rope is old","if you fall, then fall in quiet","the drake's asleep, so don't you riot","Up, up, the red rock's high","sing it under your breath, or die"],"chorus":[4,5],"tags":["road","monsters"]},{"id":"knucklebones_midnight","title":"Knucklebones at Midnight","tone":"rowdy","diff":4,"craft":"fine","meter":"4/4","lines":["Throw the bones across the tavern floor","a six, a two, a goblin's tooth","the stakes are high and so are we","and nobody is telling the truth","Throw them, throw them, roll the bones","lose your silver, keep your groans"],"chorus":[4,5],"tags":["drink"]},{"id":"wagon_wheel","title":"The Wagon Wheel Song","tone":"rowdy","diff":2,"craft":"plain","meter":"4/4","lines":["The wagon wheel came off again","the third time since the ford","we're pushing it up the King's Road","and singing, because we're bored","Push, push, roll it along","a broken wheel needs a stupid song"],"chorus":[4,5],"tags":["road"]},{"id":"whole_room_sings","title":"The Whole Room Sings","tone":"rowdy","diff":5,"craft":"fine","meter":"4/4","lines":["When the fiddle starts at the Gilded Flagon","the brass on the walls begins to ring","the guildsmen take their hats off","and every last one of them sings","Sing it, sing it, the whole room sings","louder than a hundred anvil rings"],"chorus":[4,5],"tags":["drink","home"],"town":"ironhaven"},{"id":"they_held_the_bridge","title":"They Held the Bridge","tone":"heroic","diff":5,"craft":"fine","meter":"4/4","lines":["When the bandits came for Carrbridge in the fog","six of them stood upon the span","Toll-Captain Venn said nobody crosses","without paying, and the toll was steel","Hold the bridge, hold the bridge","nobody crosses without the toll"],"chorus":[4,5],"tags":["road","monsters"],"town":"carrbridge"},{"id":"up_to_frostspire","title":"Up to Frostspire","tone":"heroic","diff":4,"craft":"plain","meter":"3/4","lines":["We went up Frostspire for the wraith's cold crown","with frozen beards and frozen feet","the wind said turn around and go home","we said the wind could take a seat","Up, up, to the frozen spire","carry the cold and carry the fire"],"chorus":[4,5],"tags":["monsters","road"],"town":"frosthold"},{"id":"goblin_camp_burned","title":"The Night the Goblin Camp Burned","tone":"heroic","diff":3,"craft":"plain","meter":"4/4","lines":["We came down on the Goblin Camp at night","with torches and a borrowed horn","the goblins ran in all directions","and Gruk ran off with one boot on","Burn bright, the goblin camp","go home, Gruk, go home damp"],"chorus":[4,5],"tags":["monsters"]},{"id":"into_emberdeep","title":"Down Into Emberdeep","tone":"heroic","diff":5,"craft":"fine","meter":"6/8","lines":["Down into Emberdeep, where the rock runs red","where the salamanders sleep in the stone","we went down six and we came up six","and one of us wore a crown of bone","Down, down, into the fire","and up again, a little higher"],"chorus":[4,5],"tags":["monsters"]},{"id":"shield_to_shield","title":"Shield to Shield","tone":"heroic","diff":3,"craft":"plain","meter":"4/4","lines":["Shield to shield and shoulder to shoulder","the wolves are many and the night is cold","every one of them is getting bolder","and every one of us is going to hold","Hold, hold, shield to shield","nothing gets through and nothing yields"],"chorus":[4,5],"tags":["monsters"]},{"id":"came_back_for_you","title":"We Came Back for You","tone":"heroic","diff":3,"craft":"plain","meter":"3/4","lines":["They said you'd fallen in the Collapsed Mine","they said there was no use in looking","we went down with a rope and a lamp","and found you, furious, and cooking","We came back, we came back for you","that's the thing a crew will do"],"chorus":[4,5],"tags":["work","road"],"town":"veldrock"},{"id":"serpent_at_the_harbour","title":"The Serpent at the Harbour Mouth","tone":"heroic","diff":4,"craft":"fine","meter":"6/8","lines":["The sea serpent coiled round the harbour mouth","and the boats sat idle in the bay","Harbourmaster Quell stood on the wall","and said that someone make it go away","Row out, row out, with spear and song","the serpent's big, but the night is long"],"chorus":[4,5],"tags":["sea","monsters"],"town":"saltmarrow"},{"id":"smallest_hero","title":"The Smallest Hero","tone":"heroic","diff":1,"craft":"clumsy","meter":"4/4","lines":["I'm the smallest hero in the guild","my sword is really more a knife","but I stabbed a giant on the toe","and he ran away for life","Small, small, but quick and mean","the best toe-stabber you have ever seen"],"chorus":[4,5],"tags":["monsters"]},{"id":"oath_at_thornwall","title":"The Oath We Took at Thornwall","tone":"heroic","diff":3,"craft":"plain","meter":"4/4","lines":["We took an oath at the Thornwall gate","with Sister Amberline's candle lit","we swore we'd see this season through","and we've seen most of it","Keep the oath, the oath keeps you","that's what Sister Amberline says is true"],"chorus":[4,5],"tags":["road"],"town":"thornwall"},{"id":"clearing_the_wolf_den","title":"Clearing the Wolf Den","tone":"heroic","diff":2,"craft":"plain","meter":"6/8","lines":["We went into the Wolf Den, a torch apiece","and the dark was full of eyes","the wolves came on and we held still","and we came out at sunrise","Howl, howl, the wolves are done","the den is ours, and so's the sun"],"chorus":[4,5],"tags":["monsters"]},{"id":"ysoldes_watch","title":"Captain Ysolde's Watch","tone":"heroic","diff":4,"craft":"fine","meter":"4/4","lines":["Captain Ysolde walks the Ironhaven wall","every night since the siege began","she's never slept, or so they say","she's half a captain, half a plan","Watch, watch, the captain's watch","sleep, Ironhaven, nothing gets past"],"chorus":[4,5],"tags":["work","monsters"],"town":"ironhaven"},{"id":"nobody_thought_wed_win","title":"Nobody Thought We'd Win","tone":"heroic","diff":2,"craft":"clumsy","meter":"4/4","lines":["Nobody thought we'd win, not even us","we didn't think it either, truth be told","we closed our eyes and swung our swords","and opened them, and there was gold","Nobody thought we'd win, but we did","we're not sure how, so keep it hid"],"chorus":[4,5],"tags":["monsters"]},{"id":"cragtooth_warren","title":"Cragtooth Warren","tone":"heroic","diff":3,"craft":"plain","meter":"3/4","lines":["In Cragtooth Warren the kobolds dig","and the tunnels twist like string","we went in after a stolen child","and we brought back everything","Dig, dig, the kobolds dig","but our crew digs twice as big"],"chorus":[4,5],"tags":["monsters"]},{"id":"the_last_arrow","title":"The Last Arrow","tone":"heroic","diff":5,"craft":"fine","meter":"6/8","lines":["One arrow left and the drake coming down","wind in my face, the crew at my back","I counted three and let it fly","and the sky went quiet, and then went black","One arrow, one breath, one shot","and that was all the luck we got"],"chorus":[4,5],"tags":["monsters"]},{"id":"march_kings_road","title":"March Along the King's Road","tone":"heroic","diff":1,"craft":"plain","meter":"4/4","lines":["March, march, along the King's Road","left foot, right foot, sing it loud","the boots are wet, the pack is heavy","and every one of us is proud","March, march, and keep in time","every mile's a mile of mine"],"chorus":[0,4,5],"tags":["road"]},{"id":"healers_stand","title":"The Healer's Stand","tone":"heroic","diff":3,"craft":"plain","meter":"4/4","lines":["When the line broke in the Ashveil Crypts","our healer didn't run, she stayed","she knelt beside the ones who'd fallen","and the dead stepped back, afraid","Stand, healer, stand your ground","the dead don't like that glowing sound"],"chorus":[4,5],"tags":["death","monsters"]},{"id":"brynjars_horn","title":"Blow the Horn, Brynjar","tone":"heroic","diff":2,"craft":"clumsy","meter":"3/4","lines":["When the frost wolves came down off the hill","Watchman Brynjar blew his horn","he blew it once, he blew it twice","he blew it till the horn was worn","Toot the horn, toot the horn","Brynjar's lungs have never been so torn"],"chorus":[4,5],"tags":["monsters","home"],"town":"frosthold"},{"id":"rangers_promise","title":"The Ranger's Promise","tone":"heroic","diff":3,"craft":"plain","meter":"6/8","lines":["Ranger Holt walks the Greenwood every dawn","with a bow and a dog and a song","he says the trees tell him where trouble is","and the trees have never been wrong","Walk soft, walk soft, through the green","the ranger sees what can't be seen"],"chorus":[4,5],"tags":["road","monsters"],"town":"hollowood"},{"id":"fought_a_dragon_sort_of","title":"We Fought a Dragon (Sort Of)","tone":"heroic","diff":2,"craft":"clumsy","meter":"4/4","lines":["We fought a dragon on the Redcrag slope","well, more a drake, a little one","well, it was sleeping, and we were quiet","well, we left. But we could have. Everyone","We fought a dragon, sort of, nearly","tell it big, and tell it dearly"],"chorus":[4,5],"tags":["monsters"]},{"id":"seven_up_the_shaft","title":"Seven Up the Shaft","tone":"heroic","diff":4,"craft":"plain","meter":"4/4","lines":["Seven went down the Veldrock shaft","the day the old tunnel fell","we dug with picks and dug with spoons","and seven came back up as well","Up, up, out of the dark","every lamp lit, every spark"],"chorus":[4,5],"tags":["work"],"town":"veldrock"},{"id":"plank_across_the_bog","title":"Across the Bog on a Plank","tone":"heroic","diff":1,"craft":"clumsy","meter":"6/8","lines":["We crossed the bog upon a plank","the plank was short, the bog was wide","we moved the plank and moved again","it took all day to reach the other side","Plank, plank, step and swap","heroes never stop, heroes plop"],"chorus":[4,5],"tags":["road"],"town":"ashfen"},{"id":"fern_fire_in","title":"Fern Keeps the Fire In","tone":"tender","diff":2,"craft":"plain","meter":"3/4","lines":["Fern keeps the fire in at the Watching Oak","whatever the hour you knock","she'll find you a bowl and a blanket too","and never once look at the clock","the roof leaks over the second stair","and the cat sleeps in the crock","the door's on the latch and the fire's in"],"chorus":[6],"tags":["home","drink"],"town":"hollowood","form":"refrain"},{"id":"third_step","title":"Mind the Third Step","tone":"funny","diff":1,"craft":"clumsy","meter":"4/4","lines":["The Pickaxe and Pint has a crooked stair","the third step's taller than the rest","Mother Grall puts a lamp on it","the lamp falls down with all the rest","I've tripped it sober, I've tripped it not","I tripped it once in my Sunday best","down I go, and up I get"],"chorus":[6],"tags":["drink","home"],"town":"veldrock","form":"refrain"},{"id":"salt_on_the_wind","title":"Salt on the Wind","tone":"sad","diff":3,"craft":"fine","meter":"6/8","lines":["He went out with the herring fleet","the morning the gulls flew low","Mother Tide rang the harbour bell","but the boats were out, and so","I keep his boots by the kitchen door","with the laces tied in a bow","and the salt comes in on the wind"],"chorus":[6],"tags":["sea","death","love"],"town":"saltmarrow","form":"refrain"},{"id":"brasks_lantern","title":"Brask's Lantern","tone":"dark","diff":3,"craft":"plain","meter":"4/4","lines":["Sergeant Brask walks Thornwall when the bell strikes two","with a lantern and a key","he tries the lock on the baker's door","he looks up the old oak tree","nobody asks what he's looking for","and nobody wants to see","swing, lantern, swing low"],"chorus":[6],"tags":["work","monsters"],"town":"thornwall","form":"refrain"},{"id":"toll_captains_fiddle","title":"The Toll-Captain's Fiddle","tone":"funny","diff":2,"craft":"plain","meter":"3/4","lines":["Toll-Captain Venn took up the fiddle","and charges you to hear it played","a copper a verse, two for the chorus","and three if you want it to stop","the river men pay to go under the bridge","the bargewomen pay to go deaf","pay the man, pay the man"],"chorus":[6],"tags":["work","road"],"town":"carrbridge","form":"refrain"},{"id":"whitepeak_pass","title":"Over the Whitepeak Pass","tone":"heroic","diff":4,"craft":"fine","meter":"6/8","lines":["We went up over the Whitepeak pass","with the snow to the horses' knees","Brynjar's horn behind us blew","and the wind tore through the trees","nobody turned and nobody fell","and we came down by degrees","up and over, and over, and home"],"chorus":[6],"tags":["road","home"],"town":"frosthold","form":"refrain"},{"id":"spoon_song","title":"The Spoon Song","tone":"odd","diff":1,"craft":"clumsy","meter":"4/4","lines":["I found a spoon in the Goblin Camp","the finest spoon I've ever seen","I've eaten soup with it since spring","I've never washed it, but it's clean","the goblins want it back, I hear","they've sent a note, the note is mean","it is a very good spoon"],"chorus":[6],"tags":["monsters","home"],"form":"refrain"},{"id":"rooks_ledger","title":"Rook's Ledger","tone":"dark","diff":3,"craft":"plain","meter":"4/4","lines":["Guildmaster Rook keeps a ledger","of every debt in Thornwall town","he wrote my name in it twice in red","and underlined it, and then frowned","I paid the first, I'm paying the second","I'll pay the third when I come round","write it down, Rook, write it down"],"chorus":[6],"tags":["work"],"town":"thornwall","form":"refrain"},{"id":"haul_the_net","title":"Haul the Net","tone":"rowdy","diff":2,"craft":"plain","meter":"4/4","lines":["Who's on the net when the gulls come in?","Saltmarrow, Saltmarrow!","Who's in the boat when the wind blows thin?","Saltmarrow, Saltmarrow!","Who'll buy the herring when it's all hauled in?","Not Saltmarrow, never!","haul it up and haul it home","the sea can keep the ones it owns"],"chorus":[6,7],"tags":["sea","work"],"town":"saltmarrow","form":"call","resp":[1,3,5]},{"id":"down_and_up_again","title":"Down the Shaft and Up Again","tone":"heroic","diff":2,"craft":"plain","meter":"4/4","lines":["Who goes down when the lamp is lit?","We go down!","Who comes up with the silver bit?","We come up!","Who's below when the timbers split?","Not today!","down the shaft and up again","Warden Plumb counts every head"],"chorus":[6,7],"tags":["work"],"town":"veldrock","form":"call","resp":[1,3,5]},{"id":"what_the_yeti_said","title":"What Did the Yeti Say?","tone":"odd","diff":2,"craft":"clumsy","meter":"6/8","lines":["What did the yeti say to me?","Nothing at all!","What did I say to the yeti, then?","Nothing at all!","we sat in snow till the sun went down","and that was the best talk of all"],"chorus":[4,5],"tags":["monsters"],"town":"frosthold","form":"call","resp":[1,3]},{"id":"bridge_still_up","title":"Is the Bridge Still Up?","tone":"funny","diff":2,"craft":"plain","meter":"4/4","lines":["Is the bridge still up in Carrbridge?","Still up today!","Has the toll gone up again?","Up again, they say!","Who's paying for the bridge, then?","We are, we pay!","pay the man and cross the water","pay again to come back over"],"chorus":[6,7],"tags":["road","work"],"town":"carrbridge","form":"call","resp":[1,3,5]},{"id":"gravediggers_roll","title":"The Gravedigger's Roll-Call","tone":"dark","diff":4,"craft":"fine","meter":"3/4","lines":["Mister Quiet calls the names at dusk","Here, says the fen","he calls the ones gone down this year","Here, says the fen","he calls my name, I hold my breath","Not yet, says the fen","count them in and count them out","the fen keeps every count"],"chorus":[6,7],"tags":["death"],"town":"ashfen","form":"call","resp":[1,3,5]},{"id":"who_ate_the_pie","title":"Who Ate the Pie?","tone":"funny","diff":1,"craft":"clumsy","meter":"4/4","lines":["Who ate the pie on Old Hesk's sill?","Not me, not me!","Who's got crumbs on their collar still?","Not me, not me!","Who's paying Old Hesk for the pie?","Oh. Me.","a pie-dish bare and a window wide","and a crumb on every side"],"chorus":[6,7],"tags":["home","drink"],"town":"thornwall","form":"call","resp":[1,3,5]},{"id":"answer_the_horn","title":"Answer the Horn","tone":"heroic","diff":3,"craft":"plain","meter":"3/4","lines":["When Brynjar's horn blows on the wall","We answer the horn!","when the frost wolves come and the torches fall","We answer the horn!","stand in the gate and stand up tall","the cold won't take us all"],"chorus":[4,5],"tags":["monsters","home"],"town":"frosthold","form":"call","resp":[1,3]},{"id":"anybody_home","title":"Is Anybody Home?","tone":"sad","diff":3,"craft":"plain","meter":"6/8","lines":["Is anybody home in the empty camp?","Only the wind","Is anybody waiting with a lamp?","Only the wind","we left a fire and a pot of tea","and the wind keeps both for me"],"chorus":[4,5],"tags":["road","death"],"form":"call","resp":[1,3]},{"id":"drowned_bell","title":"The Ballad of the Drowned Bell","tone":"dark","diff":4,"craft":"fine","meter":"3/4","lines":["They cast a bell for Saltmarrow's temple","the biggest bell in the west","they rowed it out on a flat-bottomed barge","to hang it where it rang best","a squall came up off the Salt Cliffs","and the barge went down with its guest","now the bell rings under the water","on every night of the year","Mother Tide says it's only the current","and the fishermen don't go near","ring, bell, under the sea","ring for the boats and ring for me"],"chorus":[10,11],"tags":["sea","death"],"town":"saltmarrow","form":"ballad"},{"id":"nettle_and_wolf","title":"Granny Nettle and the Wolf","tone":"odd","diff":3,"craft":"plain","meter":"6/8","lines":["Granny Nettle went out for nettles","in the Greenwood, late in the day","a grey wolf stood across the path","and would not get out of the way","she gave it the look she keeps for grandsons","she gave it a sprig of rue","the wolf sat down and the wolf lay down","and the wolf walked her home, it's true","mind your manners in the Greenwood","Granny Nettle's coming through"],"chorus":[8,9],"tags":["monsters","road"],"town":"hollowood","form":"ballad"},{"id":"long_road_ironhaven","title":"The Long Road to Ironhaven","tone":"heroic","diff":3,"craft":"plain","meter":"4/4","lines":["We set out from Thornwall with a borrowed cart","and a map we couldn't read","we lost the map at Carrbridge","and the cart in the Ashfen reed","we crossed the Redcrag on our hands","with a goat we didn't need","we fought three bandits and a bear","the bear was very good indeed","and we came into Ironhaven","with the bells all ringing high","the road is long and the road is ours","and we'll walk it by and by"],"chorus":[10,11],"tags":["road"],"town":"ironhaven","form":"ballad"},{"id":"third_coat_widow","title":"The Coat on the Hook","tone":"sad","diff":4,"craft":"fine","meter":"3/4","lines":["Big Inga keeps a coat on a hook","by the door of the Third Coat inn","it belonged to a man who went for wood","the winter the wolves came in","she's never moved it, she never will","she brushes the frost from the sleeves","and some nights late when the fire is low","she pours him a cup, and leaves","hang it high and hang it warm","for the one who's coming home"],"chorus":[8,9],"tags":["love","death","home"],"town":"frosthold","form":"ballad"},{"id":"undertakers_daughter","title":"The Undertaker's Daughter","tone":"tender","diff":3,"craft":"plain","meter":"6/8","lines":["The undertaker's daughter sings","to the ones laid out in the back","she sings them songs they used to know","and the dead don't answer back","she sang one night to a sleeping drunk","who'd wandered in from the rain","he woke and he wept and he married her","and he's never touched drink again","sing low, sing low in Ashfen","where the quiet ones lie down"],"chorus":[8,9],"tags":["love","death"],"town":"ashfen","form":"ballad"},{"id":"nine_goblins_goose","title":"Nine Goblins and a Goose","tone":"funny","diff":2,"craft":"clumsy","meter":"4/4","lines":["Nine goblins came down the King's Road","with a goose they'd stolen in Thornwall","the goose was loud and the goose was cross","and the goose was the boss of them all","we met them by the Carrbridge toll","and asked them what they were about","the goose said honk, the goblins ran","and that's the end of that, no doubt","except the goose came home with us","and she's in charge now, by the way","honk, honk, the goose is boss","and the goose is here to stay"],"chorus":[10,11],"tags":["monsters","road"],"form":"ballad"},{"id":"mine_bell","title":"When the Mine Bell Rings","tone":"sad","diff":5,"craft":"fine","meter":"4/4","lines":["The mine bell rings once for the shift","and twice for the shift come home","three times means a tunnel's down","and nobody likes to be alone","I heard it ring three times in spring","and I ran with a lamp and a spade","we dug till the bell rang twice again","and Brother Coal knelt down and prayed","ring it twice, ring it twice","bring them up into the light"],"chorus":[8,9],"tags":["work","death"],"town":"veldrock","form":"ballad"},{"id":"ostravas_rule","title":"Ostrava's Rule","tone":"rowdy","diff":2,"craft":"plain","meter":"4/4","lines":["Madame Ostrava runs the Gilded Flagon","with a ladle and a look","no swords on tables, no boots on the bar","and no singing from the book","but when the bell strikes midnight","she climbs up on a chair","one more round, says Ostrava","and one more after that"],"chorus":[6,7],"tags":["drink"],"town":"ironhaven"},{"id":"watchmans_lullaby","title":"Watchman's Lullaby","tone":"tender","diff":2,"craft":"fine","meter":"3/4","lines":["Sleep now, Frosthold, the watch is set","Brynjar's on the wall","the wolves are far and the snow is soft","and nothing comes at all","hush now, hush now, the stars are out","and the horn won't blow tonight"],"chorus":[4,5],"tags":["home"],"town":"frosthold"},{"id":"damps_complaint","title":"Constable Damp's Complaint","tone":"funny","diff":1,"craft":"clumsy","meter":"4/4","lines":["Constable Damp has a cold again","he's had it since the day he was born","he walks the fen in three wet coats","and a hat that's soaked and torn","atchoo, atchoo, the law is here","stand back and pass the handkerchief"],"chorus":[4,5],"tags":["work","home"],"town":"ashfen"},{"id":"last_lamp","title":"The Last Lamp in the Academy","tone":"odd","diff":4,"craft":"fine","meter":"6/8","lines":["Archivist Pell keeps one lamp lit","in the Academy's highest room","she's reading a book that reads her back","and it's turned a page since noon","turn the page, Pell, turn it slow","some books like to be read alone"],"chorus":[4,5],"tags":["home","work"],"town":"ironhaven"},{"id":"hollowood_wedding","title":"A Wedding Under the Oak","tone":"rowdy","diff":3,"craft":"plain","meter":"6/8","lines":["There's a wedding under the Watching Oak","and the whole of Hollowood's come","the bride's in moss and the groom's in bark","and the elder's had too much rum","Elder Mossback dances on a root","and the root decides to move","kiss the bride and mind the roots","the oak is in the mood"],"chorus":[6,7],"tags":["love","drink"],"town":"hollowood"},{"id":"ferry_in_the_dark","title":"The Ferry in the Dark","tone":"dark","diff":3,"craft":"fine","meter":"3/4","lines":["There's a ferry runs from Carrbridge","on the nights there is no moon","the ferryman doesn't take your coin","he takes your second-best tune","hum it soft and hum it true","he'll hum it back to you"],"chorus":[4,5],"tags":["road","death"],"town":"carrbridge"},{"id":"amberlines_candle","title":"Sister Amberline's Candles","tone":"tender","diff":1,"craft":"plain","meter":"4/4","lines":["Sister Amberline lights a candle","for every hero on the road","she's running out of shelf for them","the temple's running out of tallow","one for the living, one for the lost","and one for the ones who don't know"],"chorus":[4,5],"tags":["home","road"],"town":"thornwall"}],"folk":[{"id":"green_sleeve","tone":"tender","world_title":"The Green Sleeve","teller":"as the Hollowood pipers have it","real_title":"Greensleeves","town":"hollowood","meter":"3/4","bpm":96,"key":"A minor","notes":"A2 | c4 d2 | e3 f1 e2 | d4 B2 | G3 A1 B2 | c4 A2 | A3 ^G1 A2 | B4 ^G2 | E4 A2 | c4 d2 | e3 f1 e2 | d4 B2 | G3 A1 B2 | c3 B1 A2 | ^G3 ^F1 ^G2 | A6 | g6 | g3 f1 e2 | d4 B2 | G3 A1 B2 | c4 A2 | A3 ^G1 A2 | B4 ^G2 | E6 | g6 | g3 f1 e2 | d4 B2 | G3 A1 B2 | c3 B1 A2 | ^G3 ^F1 ^G2 | A4"},{"id":"parsley_thyme","tone":"sad","world_title":"Parsley, Sage and Thyme","teller":"an Ashfen herb-seller's air","real_title":"Scarborough Fair","town":"ashfen","meter":"3/4","bpm":92,"key":"D dorian","notes":"D4 D2 | A4 A2 | E3 F1 E2 | D6 | z2 A2 c2 | d4 c2 | A2 B2 G2 | A6 | z4 d2 | d4 d2 | c4 A2 | A2 G2 F2 | E2 C4 | D4 A2 | G4 F2 | E2 D2 C2 | D6"},{"id":"bosuns_morning","tone":"rowdy","world_title":"The Bosun's Morning","teller":"hauled on every Saltmarrow deck","real_title":"Drunken Sailor","town":"saltmarrow","meter":"4/4","bpm":112,"key":"D dorian","notes":"A2 A1 A1 A2 A1 A1 | A2 D2 F2 A2 | G2 G1 G1 G2 G1 G1 | G2 C2 E2 G2 | A2 A1 A1 A2 A1 A1 | A2 B2 c2 d2 | c2 A2 G2 E2 | D4 D4 | A4 A4 | A2 D2 F2 A2 | G4 G4 | G2 C2 E2 G2 | A4 A4 | A2 B2 c2 d2 | c2 A2 G2 E2 | D4 D4"},{"id":"old_long_since","tone":"tender","world_title":"Old Long Since","teller":"piped at Carrbridge when the year turns","real_title":"Auld Lang Syne","town":"carrbridge","meter":"4/4","bpm":80,"key":"G major","notes":"D2 | G3 G1 G2 B2 | A3 G1 A2 B2 | G3 G1 B2 d2 | e6 e2 | d3 B1 B2 G2 | A3 G1 A2 B2 | G3 E1 E2 D2 | G6 e2 | d3 B1 B2 G2 | A3 G1 A2 e2 | d3 B1 B2 d2 | e6 g2 | d3 B1 B2 G2 | A3 G1 A2 B2 | G3 E1 E2 D2 | G6"},{"id":"washing_line","tone":"rowdy","world_title":"The Washing-Line Jig","teller":"a Thornwall wash-day tune","real_title":"The Irish Washerwoman","town":"thornwall","meter":"6/8","bpm":116,"key":"G major","notes":"d1 c1 | B1 G1 G1 D1 G1 G1 | B1 G1 B1 d1 c1 B1 | c1 A1 A1 E1 A1 A1 | c1 A1 c1 e1 d1 c1 | B1 G1 G1 D1 G1 G1 | B1 G1 B1 d1 c1 B1 | c1 B1 c1 A1 d1 c1 | B1 G1 G1 G1"},{"id":"brother_bell","tone":"funny","world_title":"Brother Bellringer","teller":"a round the Ironhaven apprentices sing to stay awake","real_title":"Frère Jacques","town":"ironhaven","meter":"4/4","bpm":104,"key":"F major","notes":"F2 G2 A2 F2 | F2 G2 A2 F2 | A2 _B2 c4 | A2 _B2 c4 | c1 d1 c1 _B1 A2 F2 | c1 d1 c1 _B1 A2 F2 | F2 C2 F4 | F2 C2 F4"},{"id":"by_moonlight","tone":"tender","world_title":"By the Light of the Moon","teller":"a Frosthold lullaby for the long nights","real_title":"Au clair de la lune","town":"frosthold","meter":"4/4","bpm":84,"key":"C major","notes":"C2 C2 C2 D2 | E4 D4 | C2 E2 D2 D2 | C8 | C2 C2 C2 D2 | E4 D4 | C2 E2 D2 D2 | C8 | D2 D2 D2 D2 | A,4 A,4 | D2 C2 B,2 A,2 | G,8 | C2 C2 C2 D2 | E4 D4 | C2 E2 D2 D2 | C8"},{"id":"miners_daughter","tone":"sad","world_title":"The Miner's Daughter","teller":"sung slow in Veldrock for the ones the shafts kept","real_title":"Oh My Darling, Clementine","town":"veldrock","meter":"3/4","bpm":100,"key":"F major","notes":"F1 F1 | F3 C1 A1 A1 | A3 F1 F1 A1 | c3 c1 _B1 A1 | G4 G1 A1 | _B3 _B1 A1 G1 | A3 F1 F1 A1 | G3 C1 E1 G1 | F4"},{"id":"bridge_falling","tone":"funny","world_title":"The Bridge Is Falling","teller":"a Carrbridge game-song, sung on the old bridge to annoy the toll","real_title":"London Bridge Is Falling Down","town":"carrbridge","meter":"4/4","bpm":108,"key":"C major","notes":"G3 A1 G2 F2 | E2 F2 G4 | D2 E2 F4 | E2 F2 G4 | G3 A1 G2 F2 | E2 F2 G4 | D4 G4 | E2 C6"},{"id":"star_counter","tone":"tender","world_title":"The Star-Counter's Tune","teller":"what Frosthold children hum to count the stars on the long nights","real_title":"Ah! vous dirai-je, maman (Twinkle, Twinkle)","town":"frosthold","meter":"4/4","bpm":96,"key":"C major","notes":"C2 C2 G2 G2 | A2 A2 G4 | F2 F2 E2 E2 | D2 D2 C4 | G2 G2 F2 F2 | E2 E2 D4 | G2 G2 F2 F2 | E2 E2 D4 | C2 C2 G2 G2 | A2 A2 G4 | F2 F2 E2 E2 | D2 D2 C4"},{"id":"footbridge_dance","tone":"rowdy","world_title":"The Footbridge Dance","teller":"danced on the Hollowood footbridge at harvest, two by two","real_title":"Sur le pont d'Avignon","town":"hollowood","meter":"4/4","bpm":112,"key":"C major","notes":"C1 C1 C2 D1 D1 D2 | E1 F1 G1 C1 B,1 C1 D1 G,1 | C1 C1 C2 D1 D1 D2 | E1 F1 G1 C1 D1 B,1 C2 | C1 C1 C2 D1 D1 D2 | E1 F1 G1 C1 B,1 C1 D1 G,1 | C1 C1 C2 D1 D1 D2 | E1 F1 G1 C1 D1 B,1 C2"},{"id":"weasels_jig","tone":"funny","world_title":"The Weasel's Jig","teller":"a Thornwall pawnshop tune; the weasel is the coat you pawn","real_title":"Pop Goes the Weasel","town":"thornwall","meter":"6/8","bpm":104,"key":"C major","notes":"C2 C1 D2 D1 | E1 G1 E1 C2 G,1 | C2 C1 D2 D1 | E3 C2 G,1 | C2 C1 D2 D1 | E1 G1 E1 C3 | A3 D2 F1 | E3 C3"},{"id":"feather_cap","tone":"heroic","world_title":"The Feather in the Cap","teller":"the tune the Ironhaven apprentices march to on guild day","real_title":"Yankee Doodle","town":"ironhaven","meter":"4/4","bpm":112,"key":"C major","notes":"C2 C2 D2 E2 | C2 E2 D2 G,2 | C2 C2 D2 E2 | C4 B,4 | C2 C2 D2 E2 | F2 E2 D2 C2 | B,2 G,2 A,2 B,2 | C4 C4"},{"id":"grey_water","tone":"sad","world_title":"Over the Grey Water","teller":"what Saltmarrow wives sing at the harbour wall","real_title":"My Bonnie Lies over the Ocean","town":"saltmarrow","meter":"3/4","bpm":88,"key":"C major","notes":"G,2 | E3 D1 C2 | D2 C2 A,2 | G,2 E,4 | z4 G,2 | E3 D1 C2 | C2 B,2 C2 | D6 | z4 G,2 | E3 D1 C2 | D2 C2 A,2 | G,2 E,4 | z4 G,2 | A,2 D2 C2 | B,2 A,2 B,2 | C4"}]}};